INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (3, 'Merck KGaA – Life Science (MilliporeSigma / Sigma-Aldrich / Merck Millipore)', 'MilliporeSigma (USA/Canada), Sigma-Aldrich, Merck Millipore, Millipore, EMD Millipore, SAFC, Supelco, BioReliance', 'Darmstadt', 'Germany', 'Merck KGaA', 'Subsidiary/business sector of Merck KGaA (public, FWB: MRK; majority held by the Merck family via E. Merck KG)', 1668, 'https://www.sigmaaldrich.com', 'Life-science instruments & reagents', 62000, 2024, 'Merck KGaA group headcount (~62,000); the Life Science business sector employs roughly 28,000 (recalled, unverified).', 'EUR 9.26 billion', 10188, 'FY2024', 'segment', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Life Science sector net sales ~EUR 9,262 million in 2024 (group net sales ~EUR 21.2 billion). FY2025 figures not verified. Converted at EUR 1.10.', 'reported', 'subsidiary', 'Searched Sigma-Aldrich Israel/Rehovot generically, Merck/Milli-Q on Israeli distributor domains and sigmaaldrich.com/merckmillipore.com office pages. Sigma-Aldrich''s contact page lists ''Sigma-Aldrich Israel Ltd., an affiliate of Merck KGaA, Darmstadt, Germany'' at 3 Plaut St., Rehovot 7670603 (site self-assessment: operating since 1989, producing antibodies, primers and peptides), and Merck ISO certificates list a Jerusalem (Har Hotzvim) site, confirming Merck''s own Israeli entity. For lab equipment, Mercury Scientific & Industrial Products (part of Gadot since 2022) describes itself as the exclusive Israeli representative for Merck Milli-Q lab-water systems and distributor of Merck KGaA''s life-science and chemicals divisions, so Milli-Q is sold via Mercury rather than direct; this is self-reported on Mercury''s site and not independently confirmed by Merck.', 'high', 'Subsidiary confirmed on the manufacturer''s own contact page and certificates; Milli-Q distributor role is the distributor''s own statement.', 'parent', 'verified', '+972 8 948 4222 / +972 8 948 4100', 'isrcustserv@merckgroup.com', '3 Plaut St., Rehovot 7670603, Israel', 'https://www.sigmaaldrich.com/collections/offices', 'Israel office (Sigma-Aldrich Israel Ltd., Rehovot) per Merck''s official office listing; fax +972 8 948 4200; technical service isrtechserv@merckgroup.com (older page versions show the @emdgroup.com domain); a third-party directory gives +972 8 948 4100 as the main line.');
