INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (4, 'Waters Corporation', 'TA Instruments, Wyatt Technology, Waters Biosciences (ex-BD Biosciences), Waters Advanced Diagnostics (ex-BD Diagnostic Solutions)', 'Milford, Massachusetts', 'USA', '', 'Public (NYSE: WAT)', 1958, 'https://www.waters.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 7800, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Stand-alone Waters, ~7,800 employees (2024 10-K). The combination with BD''s Biosciences & Diagnostic Solutions business (announced 14 Jul 2025, Reverse Morris Trust, ~USD 17.5 billion; expected to close around end of Q1 calendar 2026) roughly doubles headcount (~16,000) and revenue (~USD 6.5 billion pro forma) - closing status and combined figures NOT verified in this session.', 'USD 2.96 billion', 2958, 'FY2024', 'company', 'FY2024 stand-alone figure. On 9 Feb 2026 Waters completed the Reverse Morris Trust combination with BD''s Biosciences & Diagnostic Solutions businesses; the combined company has pro-forma revenue of roughly USD 6.5 billion and ~16,000 employees (deal announcement, not re-verified).', 'reported', 'distributor', 'Waters'' 10-K Exhibit 21.1 lists an Israeli subsidiary, Waters (TC) Israel Ltd. (seen in a search excerpt; the page itself could not be opened). Whether LC/MS instruments are sold direct or through an Israeli distributor was not established – to verify in the next round. TA Instruments'' Middle East directory lists Bargal (Shoham / Airport City) for thermal analysis, rheology, microcalorimetry, dilatometry and thermal conductivity.', 'medium', '', 'company', 'verified', '+1 508 478 2000', '', '34 Maple Street, Milford, MA 01757, USA', '', 'HQ — Israel office (Waters (TC) Israel Ltd.) not found in 2 searches (results were Israeli water utilities); Waters says local offices/distributors are listed on waters.com; HQ details from a GlobalData profile.');
