INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (12, 'Avantor (incl. VWR)', 'VWR; J.T.Baker; Macron Fine Chemicals; NuSil; Masterflex', 'Radnor, Pennsylvania', 'USA', '', 'Public (NYSE: AVTR)', 1904, 'https://www.avantorsciences.com', 'Lab distribution & own-brand products', 13500, 2025, 'Figure shown consistently by PitchBook, Tracenable and Motley Fool (likely from the FY2025 10-K human-capital section); Revelio Labs shows ~14,600. The 10-K (sec.gov avtr-20251231.htm) could not be opened (fetch failure).', 'USD 6.55 billion', 6552, 'FY2025', 'company', 'Company Q4/FY2025 press release: net sales USD 6.55B, down 3% (organic -3%); net loss USD 530M. EDGAR-derived figure 6,552 (USD millions) vs 6,784 in FY2024.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Round 3 ran four searches: the brand restricted to the 40 Israeli distributor domains (only SEC filings surfaced; no Israeli lab-supply site mentions VWR or Avantor), a Hebrew-only query ''VWR Avantor יבואן נציגות בישראל ציוד מעבדה'' (only acquisition news and a VWR International GmbH exhibitor listing that cites a Dubai hub), an ''Israel'' query restricted to vwr.com/avantorsciences.com (no Israel page) and an extended English query (no Israeli partner named). VWR describes itself as Avantor''s direct selling channel serving customers in ~180 countries, so Israel is probably served directly from Avantor/VWR Europe or through unnamed local resellers, but no Israeli entity could be identified.', 'low', 'Absence of evidence only; no source names an Israeli VWR/Avantor subsidiary or distributor.', 'company', 'partial', '+1 610 386 1700', '', 'One Radnor Corporate Center, Building One, Suite 200, 100 Matsonford Road, Radnor, PA 19087, USA', 'https://corporate.avantorsciences.com/us/en/contact', 'HQ (official contact page); customer support toll-free +1 855 282 6867 (US) / +1 610 573 2600 (outside US); support emails redacted in results; North American office 600 Hamilton Street, 8th Floor, Allentown, PA 18101.');
