INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (19, 'SCIEX (Danaher)', 'AB SCIEX; Applied Biosystems/MDS Sciex', 'Framingham, Massachusetts', 'USA', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 1969, 'https://sciex.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 2000, 2025, 'Approximate SCIEX headcount (~2,000); parent Danaher ~60,000. Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Life Sciences segment)', 7300, 'FY2025', 'segment', 'Danaher Life Sciences segment ~USD 7.3B FY2025; SCIEX alone not disclosed.', 'mixed', 'distributor', 'Rhenium announced it became SCIEX''s Israeli distributor effective 1 April 2025 (Rhenium site + LinkedIn posts); Agentek (1987) Ltd. was the previous distributor. Not confirmed on sciex.com (page could not be opened).', 'medium', 'Distributor change is well described by the new distributor (Rhenium) and a SCIEX-visit post, but not confirmed on sciex.com; size data are parent/segment secondary figures.', 'estimate', 'verified', '+1 877-740-2129', 'sciexnow@sciex.com', '250 Forest Street, Marlborough, MA 01752, USA', 'https://sciex.com/contact-us', 'HQ (legal entity AB Sciex LLC; official contact page) — the Framingham address in the targets file (500 Old Connecticut Path) now appears under Americas sales/service; phone is from third-party directories (unverified; the official page''s listed +48 22 885 64 80 appears to be a regional line); support requests via sciex.com/request-support.');
