INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (24, 'New England Biolabs', 'NEB; brands Q5, NEBNext, Monarch, Luna, NEBuilder, NEBExpress', 'Ipswich, Massachusetts', 'USA', '', 'Private', 1974, 'https://www.neb.com', 'Life-science instruments & reagents', 1000, 2024, 'Approximately 1,000 employees worldwide (company statements). Figures recalled from company statements / filings and not re-verified online in this session.', 'USD ~500 million (trade estimate; private)', 500, '2024 (estimate)', 'estimate', 'NEB is privately held and does not publish revenue; trade estimates are in the USD 400-600M range.', 'estimate', 'distributor', 'Search ''"New England Biolabs" Israel distributor'' returned the FISEB (Federation of Israeli Societies of Experimental Biology) vendors page, where Ornat BioChemicals & Lab Equipment describes itself as a privately owned Israeli life-science sales company (25+ years) representing ''top international brands such as New England Biolabs (NEB)''. NEB''s own international ordering-support page states NEB sells abroad through exclusive distributors, agents and subsidiaries with a per-country list; the Israel entry was not visible in search snippets and the page could not be fetched, so the Ornat-NEB link rests on the Ornat/FISEB source (consistent with the brief''s hint list, where Ornat appears). Hebrew search could not be run (budget exhausted). Tool limits in this session: the shared web-search budget was exhausted after the first round of searches and all page fetches (WebFetch/curl) were blocked, so manufacturer distributor/contact pages could not be opened and some Hebrew searches could not be run. Size figures marked ''recalled'' come from company filings/pages as known to the researcher (knowledge to mid-2026) and were not re-verified against a fetched source.', 'medium', 'Israel distributor (Ornat) is supported by one credible third-party listing quoting the distributor itself, not by NEB''s own country list; size figures unavailable (private).', 'estimate', 'verified', '+1 978-928-5054', 'info@neb.com', '240 County Road, Ipswich, MA 01938-2723, USA', 'https://www.neb.com/en-us/support/international-ordering-support', 'HQ (official NEB page); toll-free +1 800-632-5227, fax +1 978-921-1350; Germany: NEB GmbH +49 69 305 23140, info.de@neb.com; UK +44 1462 420616; France +33 1 69 90 87 15, info.fr@neb.com; other countries via the subsidiary/distributor list on the same page.');
