INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (25, 'Bio-Techne', 'R&D Systems, Novus Biologicals, Tocris Bioscience, ProteinSimple, Advanced Cell Diagnostics (ACD / RNAscope), Asuragen, Lunaphore, ExosomeDx', 'Minneapolis, Minnesota', 'USA', '', 'Public (NASDAQ: TECH)', 1976, 'https://www.bio-techne.com', 'Life-science instruments & reagents', 3100, 2025, 'Approximately 3,100 employees (Bio-Techne 10-K for FY ended 30 Jun 2025; recalled, not re-verified).', 'USD 1.2 billion', 1200, 'FY2025 (ended 30 Jun 2025)', 'company', 'FY2025 net sales approx. USD 1.2 billion (about USD 1.21-1.22 bn; recalled from company results, not re-verified). FY2026 (ended Jun 2026) results released Aug 2026 were not accessible in this session.', 'reported', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Bio-Techne''s Novus Biologicals distributor page lists an Israeli distributor at 6 Hasadna St., P.O. Box 8006, Kfar Saba 4442405 with phone and e-mail, but the company name was not in the excerpt and a follow-up search for that address did not identify it; the R&D Systems distributor locator exists but showed no Israel entry in the snippets. The 40-domain sweep surfaced ENCO (self-described official Israeli distributor of 250+ antibody/protein suppliers) and Danyel, Gamidor and HyLabs pages, none of which mention R&D Systems, Novus, Tocris or ProteinSimple in any snippet. Bio-Techne''s FY2025 10-K states it ''has not historically had significant business in Russia, Ukraine or Israel''. Getter Bio-Med''s posts describe it as the official Israeli representative of Lunaphore, a Bio-Techne brand; no channel found for R&D Systems / ProteinSimple products. Novus Biologicals'' (Bio-Techne) distributor page lists an unnamed Israeli distributor at 6 Hasadna St., Kfar Saba (identity not resolved).', 'low', 'The manufacturer''s own page shows an Israeli distributor exists (Kfar Saba address) but its name was not captured; ENCO is a plausible but unconfirmed candidate.', 'company', 'partial', '+1 800-343-7475', 'techsupport@bio-techne.com', '614 McKinley Place NE, Minneapolis, MN 55413, USA', 'https://rndsystems.com/node/64566', 'HQ (listed as USA headquarters on the R&D Systems contact page — a Bio-Techne brand); North American customer service customerservice.na@bio-techne.com; third-party directories list +1 612-379-2956; UK office Abingdon and China office Shanghai with their own info@ addresses; ACD brand: info.ACD@bio-techne.com.');
