INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (26, 'Miltenyi Biotec', 'Miltenyi Biotec; MACS, CliniMACS, CliniMACS Prodigy, MACSQuant, autoMACS, gentleMACS, MACSima', 'Bergisch Gladbach', 'Germany', '', 'Private (founder-owned, Stefan Miltenyi)', 1989, 'https://www.miltenyibiotec.com', 'Cell analysis (flow cytometry / cell sorting)', 4700, 2025, 'Company boilerplate: ''more than 4,700 employees in 23 countries'' (also Randstad employer profile ~4,700). Nordkurier (regional press, Aug 2025) reports almost 4,900 employees worldwide incl. ~570 at Teterow. No 2024/2025 revenue figure found (Nordkurier only says the company aimed to pass the EUR 1 billion mark).', 'EUR ~600 million (trade estimate; private)', 660, '2024 (estimate)', 'estimate', 'No official 2024/2025 revenue figure found; Bundesanzeiger filing not seen in snippets.', 'mixed', 'distributor', 'Verified on the manufacturer''s side: Miltenyi Biotec''s ''Contact information for our global distributor network'' page (regional variants IE-en, FI-en, KR-en) lists Y.A. Almog Diagnostic & Medical Equipment Ltd., Shoham, Israel, tel. +972 3 977 33 90, info@almog.co.il, as the Israel distributor. This confirms the round-2 lead from the June-2022 Slingshot Biosciences press release describing Almog as a long-standing Israeli flow-cytometry player selling the Miltenyi MACSQuant. The Hebrew query and the Almog-domain query added nothing; Miltenyi has no Israeli subsidiary (its own entities are in Germany, USA, UK, France, Italy, Spain, Netherlands, Nordics, China, Japan, Korea, Singapore and Australia). A June 2022 Business Wire release describes Almog as a major Israeli flow-cytometry player working with Miltenyi''s MACSQuant and Cytek''s Aurora; not re-confirmed on Miltenyi''s site.', 'high', 'Manufacturer''s own distributor page names the Israeli entity; corroborated by a 2022 press release.', 'company', 'verified', '+49 2204 8306-0', 'macs@miltenyibiotec.de', 'Friedrich-Ebert-Straße 68, 51429 Bergisch Gladbach, Germany', '', 'HQ. Phone/address/email per Biocompare and Bioanalysis Zone directory listings (not the official site); press@miltenyibiotec.de appeared in a 2013 press release.');
