INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (27, '10x Genomics', '10x; Chromium, Visium, Xenium', 'Pleasanton, California', 'USA', '', 'Public (NASDAQ: TXG)', 2012, 'https://www.10xgenomics.com', 'Genomics / sequencing', 1100, 2024, 'Approximately 1,100 employees at 31 Dec 2024 (10-K; recalled, not re-verified).', 'USD 610.8 million', 611, 'FY2024', 'company', 'FY2024 revenue USD 610.8 million (10-K; recalled). FY2025 revenue (reported Feb 2026, roughly flat at ~USD 0.6 billion) could not be verified in this session.', 'reported', 'distributor', 'Searched generic queries, 27 Israeli distributor domains and 10xgenomics.com. Danyel Biotech''s own site carries a 10x Genomics brand page (Chromium Next GEM single-cell gene expression, immune profiling, ATAC) and co-hosted a 2019 Tel Aviv University seminar on the 10x portfolio, so Danyel is the Israeli distributor. 10x''s distributor locator did not expose the Israel entry in search snippets, so manufacturer-side confirmation is missing; Visium/Xenium were not seen on Danyel''s page. 10x Genomics'' Scale Bio distributors page lists Lifegene (Mevo Horon) for Israel; Danyel Biotech has the 10x brand page for Chromium/Visium/Xenium.', 'medium', 'Distributor''s own brand page plus a 2019 university event; no manufacturer-side listing seen.', 'company', 'verified', '+1 925 401 7300', '', '6230 Stoneridge Mall Road, Pleasanton, CA 94588, USA', '', 'HQ. Address/phone from GlobalData, Creditsafe and IPOScoop profiles; no general email seen.');
