INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (28, 'Oxford Nanopore Technologies', 'ONT; MinION, GridION, PromethION, Flongle, Dorado, EPI2ME', 'Oxford', 'UK', '', 'Public (LSE: ONT)', 2005, 'https://nanoporetech.com', 'Genomics / sequencing', 1100, 2024, 'Approximately 1,100 employees (FY2024 annual report; recalled, not re-verified).', 'GBP 183.2 million', 238, 'FY2024', 'company', 'FY2024 revenue GBP 183.2 million (annual report; recalled). FY2025 results (published Mar 2026; company had guided ~20%+ growth) could not be verified in this session. Converted at GBP 1.30.', 'reported', 'distributor', 'Confirmed on the manufacturer''s own channel-partner directory: nanoporetech.com/about/channel-partners/zotal-ltd lists Zotal Ltd (Tel Aviv, Israel 6971008) as officially licensed to sell Nanopore products in Israel, with expertise areas including biopharma, infectious disease/SARS-CoV-2, environmental, microbiome and human genomics; the page exists in several language versions of the ONT site. ONT''s Gulf deal with G42 Healthcare covers GCC, Jordan, Pakistan, Egypt and Iraq - not Israel. Zotal''s own website could not be fetched to cross-check its brand list, and the Hebrew search could not be run, but the official ONT listing is sufficient. Tool limits in this session: the shared web-search budget was exhausted after the first round of searches and all page fetches (WebFetch/curl) were blocked, so manufacturer distributor/contact pages could not be opened and some Hebrew searches could not be run. Size figures marked ''recalled'' come from company filings/pages as known to the researcher (knowledge to mid-2026) and were not re-verified against a fetched source.', 'medium', 'Israel distributor confirmed by the manufacturer''s official channel-partner page (high); size figures recalled rather than re-verified (hence medium overall).', 'company', 'verified', '+44 845 034 7900', '', 'Gosling Building, Edmund Halley Road, Oxford Science Park, Oxford OX4 4DQ, UK', 'https://nanoporetech.com/ja/contact', 'HQ (Global headquarters). Phone is the EMEAI line on the official contact page (fax +44 845 034 7901); Americas +1 212 202 1712. The contact page surfaced only as localized /ja/ and /zh/ variants (English version presumably https://nanoporetech.com/contact). No general email seen; the page offers live chat and web forms.');
