INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (29, 'Pacific Biosciences', 'PacBio; Revio, Vega, Sequel II/IIe, HiFi, Kinnex, Onso, SMRT', 'Menlo Park, California', 'USA', '', 'Public (NASDAQ: PACB)', 2004, 'https://www.pacb.com', 'Genomics / sequencing', 530, 2024, 'Approximate headcount after the 2024-25 restructurings (10-K FY2024 figure recalled). Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 154.0 million', 154, 'FY2024', 'company', 'FY2024 revenue USD 154.0 million (10-K; recalled). FY2025 revenue (reported Feb 2026; guided ~USD 150-170 million) not verified in this session.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). PacBio''s own ''Global distributors'' page (pacb.com/global-distributors) was examined through two searches: one excerpt appeared to associate Israel with ''East Diagnostics'', but the follow-up search showed East Diagnostics covers Serbia, Montenegro, Bosnia and Herzegovina, North Macedonia, Croatia, Kosovo, Romania, Bulgaria, Slovenia and Albania, with Israel not in that group; the Middle East/North Africa list seen in round 1 also omits Israel. The 40-domain sweep and the Hebrew query (''PacBio Revio ריצוף יבואן נציגות בישראל'') returned only scientific papers and Revio launch news, and no Israeli distributor site mentions PacBio. PacBio sells direct in several territories, so Israel may be covered by its European direct organisation, but no Israeli entity or named partner was found.', 'low', 'Manufacturer''s distributor list shows no Israel entry; absence of evidence only.', 'estimate', 'partial', '+1 650 521 8000', '', '1305 O''Brien Drive, Menlo Park, CA 94025, USA', '', 'HQ. Address/phone from Datanyze and Plunkett Research directory profiles (GlobalData lists a differing +1 302 636 5400); no general email seen.');
