INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (30, 'Tecan Group', 'Tecan; Fluent, Freedom EVO, Veya, Spark, Infinite, Cavro, Paramit, IBL International', 'Maennedorf (Zurich)', 'Switzerland', '', 'Public (SIX: TECN)', 1980, 'https://www.tecan.com', 'Liquid handling & lab automation', 3300, 2024, 'Approximately 3,300 employees (Tecan Annual Report 2024; recalled, not re-verified).', 'CHF 934.2 million', 1093, 'FY2024', 'company', 'FY2024 sales CHF 934.2 million (annual report; recalled). FY2025 results (published Mar 2026; Tecan had guided a sales decline) not verified in this session. Converted at CHF 1.17.', 'reported', 'distributor', 'Search ''"Tecan" Israel distributor'' found a LinkedIn item by an Israeli professional describing Gamidor Diagnostics as Tecan''s partner in Israel, promoting Tecan LC-MS kits and calibrators at a 2025 conference. This is a single third-party social-media source; it could not be confirmed on tecan.com (fetch blocked) and the Hebrew query ''טקאן Tecan ישראל נציג יבואן'' and the ''Tecan Israel partner Gamidor/Eldan/Rhenium'' query were blocked by the exhausted budget. Gamidor Diagnostics appears in the brief''s list of known Israeli diagnostics distributors. The channel for Tecan''s life-science automation (Fluent/Freedom EVO/Spark) in Israel remains unestablished. Tool limits in this session: the shared web-search budget was exhausted after the first round of searches and all page fetches (WebFetch/curl) were blocked, so manufacturer distributor/contact pages could not be opened and some Hebrew searches could not be run. Size figures marked ''recalled'' come from company filings/pages as known to the researcher (knowledge to mid-2026) and were not re-verified against a fetched source.', 'low', 'Israel partner based on one LinkedIn source covering only the diagnostics line; size figures recalled.', 'company', 'verified', '+41 44 922 81 11', 'info@tecan.com', 'Seestrasse 103, 8708 Männedorf, Switzerland', '', 'HQ. Phone/address per Tecan Annual Report 2022 (fax +41 44 922 81 12); email appeared only in the IUCr supplier directory (https://circle-test.iucr.org/what-we-do/education/directories/suppliers/tecan), not confirmed on tecan.com.');
