INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, source) VALUES (57, 33, 'ZEISS Israel / Carl Zeiss SMS Ltd.', '', 'subsidiary', 'Legal entity (publisher) behind the official ZEISS Israel website zeiss.co.il; HaDolev 3, Bar Lev Industrial Park, D.N. Misgav 2015600. The site''s contact form lists ''Research Microscopy Solutions'' among the product areas it takes inquiries for, but the entity itself is ZEISS''s semiconductor (SMS/SMT) unit; a local ZEISS microscopy sales/service team was NOT confirmed.', 'https://www.zeiss.co.il', '', '', 'Karmiel', '', 'https://www.zeiss.co.il/corporate/legal-information/publisher.html');
