INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (35, 'Nikon – Healthcare Business (Nikon Instruments)', 'Nikon Instruments Inc.; Nikon Europe B.V. Healthcare; Nikon Solutions; Optos (retinal imaging, Nikon subsidiary)', 'Tokyo (Shinagawa)', 'Japan', 'Nikon Corporation', 'Public (TSE: 7731)', 1917, 'https://www.microscope.healthcare.nikon.com', 'Light microscopy & imaging', 18790, 2024, 'Nikon group consolidated headcount (approx. 18,800 as of Mar-2024); Healthcare Business headcount not disclosed. Figures recalled from company reports, NOT verified in this session (web tools unavailable) - verify before use.', 'JPY 715.0 billion (Nikon group)', 4791, 'FY ending Mar-2025', 'parent', 'Nikon group revenue; the Healthcare Business segment (microscopes, cell-culture observation, retinal imaging) is roughly JPY 110-120 billion (recalled, unverified).', 'reported', 'distributor', 'Searched ''Nikon microscope Israel distributor/נציג/יבואן'' and the brand across the Israeli distributor domains. Nikon''s microscope (Healthcare) contact directory lists Agentek Ltd. in Tel Aviv under Israel, and Agentek''s own site has a Nikon representative page with current product pages (AX/AXR, AXR MP, ECLIPSE Ji, objectives). Nikon''s corporate global-network page assigns Israel (biological and industrial microscopes) to Nikon Europe B.V., i.e. the regional subsidiary serves Israel through the local dealer Agentek. Both sides of the relationship are documented. Agentek''s own vendors page (agentek.co.il/vendors) lists the brand among the manufacturers it represents in Israel (seen in a search excerpt; the manufacturer''s own distributor page was not opened).', 'high', 'Manufacturer''s contact directory and distributor''s own brand page agree.', 'parent', 'verified', '+81 3 3773 1111', 'Bsmarketing.Sales@nikon.com', '1-5-20 Nishi-Oi, Shinagawa-ku, Tokyo 140-8601, Japan', 'https://www.healthcare.nikon.com/en/contact', 'HQ. Address/phone are the Nikon Corporation head office per Nikon Sustainability Report 2025 (no Healthcare-unit-specific line found in two searches); Healthcare Business inquiries go via web form at healthcare.nikon.com/en/contact. Email appeared on a Nikon Healthcare Asia/Oceania/Middle East page (https://www.microscope.healthcare.nikon.com/en_AOM/thank-you); regional contact page microscope.healthcare.nikon.com/contact. US: Nikon Instruments, 1300 Walt Whitman Rd, Melville, NY 11747 (aggregator).');
