INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (36, 'JEOL', 'Japan Electron Optics Laboratory; JEOL USA, JEOL (Europe), JEOL (UK)', 'Akishima, Tokyo', 'Japan', '', 'Public (TSE: 6951)', 1949, 'https://www.jeol.com', 'Electron microscopy & X-ray / materials characterization', 3900, 2024, 'Consolidated headcount approx. 3,900 (as of Mar-2024). Figures recalled from company reports, NOT verified in this session (web tools unavailable) - verify before use.', 'JPY 171.6 billion', 1150, 'FY ending Mar-2024', 'company', 'Consolidated net sales approx. JPY 171.6 billion for the year ended 31 Mar 2024 (record at the time); FY ending Mar-2025 (reportedly higher, ~JPY 180+ bn) and Mar-2026 not verified. Figures recalled from company reports, NOT verified in this session (web tools unavailable) - verify before use.', 'reported', 'distributor', 'Searched ''JEOL Israel distributor/נציג/יבואן'', the brand across the Israeli distributor domains and jeol.com. JEOL''s Service & Support page names Bargal Analytical Instruments (Shoham) as the Israel sales/service contact, and Bargal''s site carries a full JEOL electron-microscopy catalogue plus a news item saying it became JEOL''s new representative in Israel. The jeol.com page is a few years old but matches Bargal''s current site. Whether Bargal also covers JEOL NMR and mass spectrometry was not seen.', 'high', 'Manufacturer page and distributor''s own product pages agree.', 'company', 'verified', '+81 42 543 1111', '', '3-1-2 Musashino, Akishima, Tokyo 196-8558, Japan', '', 'HQ. Address/phone consistent across GlobalData, Datanyze and other directories; no general email seen; website www.jeol.co.jp.');
