INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (39, 'Rigaku Holdings', 'Rigaku Corporation; Rigaku Americas; Rigaku Europe SE; Applied Rigaku Technologies', 'Akishima, Tokyo', 'Japan', '', 'Public (TSE Prime: 268A; IPO Oct 2023, previously Carlyle-controlled)', 1951, 'https://www.rigaku.com', 'Electron microscopy & X-ray / materials characterization', 2000, 2024, 'Approximately 2,000 employees (IPO prospectus, recalled).', 'JPY ~100 billion (estimate)', 670, 'FY2024 (estimate)', 'estimate', 'Rigaku Holdings (TSE Prime 268A, listed Oct 2023) reported revenue of roughly JPY 95-100 billion for FY2024 (recalled, unverified).', 'estimate', 'distributor', 'Yarden Biotec (yarden-biotec.co.il) markets Rigaku ED-XRF analysers (e.g. NEX DE VS) in Israel on its own site, which is the only sales channel found for Rigaku lab instruments; no Israeli distributor for Rigaku XRD (MiniFlex, SmartLab, XtaLAB) was identified. Rigaku also owns Rigaku Semiconductor Instruments Ltd. in Migdal HaEmek (the former XwinSys, acquired 2019), listed on rigaku.com as a division for semiconductor metrology rather than an XRD/XRF sales office. Rigaku''s EMEA service page lists Israel as served through partners/distributors (Service.Europe@rigaku.com).', 'medium', 'XRF channel verified on distributor site; XRD channel unknown; subsidiary verified on rigaku.com but out of scope for lab sales.', 'estimate', 'verified', '+972 4 995 1051', 'info@xwinsys.com', '6 HaMehkar St., Ramat Gabriel Industrial Zone, P.O. Box 371, Migdal HaEmek 2306990, Israel', '', 'Israel office - Rigaku Semiconductor Instruments Ltd. (ex-XwinSys), address/phone per Dec-2024 press release; fax +972 4 995 1078 and email per https://rigaku.com/rigaku-divisions (still listed under the XwinSys name, email may be outdated). EMEA: Rigaku Europe SE, Hugenottenallee 167, 63263 Neu-Isenburg, Germany, RESE@rigaku.com, +49 6102 77999 51. HQ: 3-9-12 Matsubara-cho, Akishima-shi, Tokyo 196-8666, +81 42 545 8111; global support support@rigaku.com. (semiconductor-metrology office, not the lab XRD channel; EMEA: RESE@rigaku.com)');
