INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (50, 'NETZSCH Analyzing & Testing', 'NETZSCH-Gerätebau GmbH; NETZSCH Group business unit; brands DSC Caliris, STA Jupiter, TG Libra, LFA HyperFlash, DMA Eplexor, Kinexus rheometers', 'Selb, Bavaria', 'Germany', 'NETZSCH Group (Erich NETZSCH GmbH & Co. Holding KG)', 'Subsidiary of NETZSCH Group (private, family-owned, owner-managed)', 1962, 'https://analyzing-testing.netzsch.com', 'Thermal analysis & materials testing', 4000, 2025, 'PARENT scope: NETZSCH Group ''more than 4,000 employees in 36 countries'' per NETZSCH''s own exhibitor profiles (German Pavilion, Arablab/Chinaplas) and 2026 job postings. No separate headcount for the Analyzing & Testing business unit found.', 'EUR ~150 million (A&T business unit; trade estimate)', 165, '2024 (estimate)', 'estimate', 'Not recorded: only aggregator figure seen (Craft: NETZSCH Group EUR 877.1 million FY2024) - not from an official/reputable source; no A&T segment revenue found.', 'mixed', 'distributor', 'Medent Scientific Instruments (מדנט מכשור מדעי) lists NETZSCH thermal-analysis instruments on its own site with a dedicated ''NETZSCH - Germany'' supplier page and DSC/STA categories (DSC 204 F1 Phoenix, DSC 404 F1 Pegasus, DSC 3500 Sirius, STA 449 F5 Jupiter, STA 409 CD with QMS 403 skimmer coupling). Some listings are old (one about 11 years), but models such as the DSC 3500 Sirius and STA 449 F5 date the catalogue to at least the mid/late 2010s. Not cross-checked on analyzing-testing.netzsch.com (search budget), so whether Medent is the current exclusive representative is unconfirmed.', 'medium', 'Distributor''s own site only; some pages stale; manufacturer page not checked.', 'parent', 'verified', '+49 9287 881-0', 'at@netzsch.com', 'Wittelsbacherstr. 42, 95100 Selb, Germany', '', 'HQ (NETZSCH-Gerätebau GmbH). Per German Pavilion exhibitor listings and the Bayern International company database (fax +49 9287 881-505).');
