INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (52, 'Hach (Veralto)', 'Hach; Hach Lange / HACH LANGE GmbH (Europe); formerly a Danaher Water Quality operating company', 'Loveland, Colorado', 'USA', 'Veralto Corporation', 'Subsidiary of Veralto Corporation (public, NYSE: VLTO; Veralto was spun off from Danaher in October 2023)', 1947, 'https://www.hach.com', 'Water & electrochemical analysis', 17000, 2024, 'Parent Veralto headcount, approx. (Veralto reports roughly 16,000-17,000 associates in its recent 10-Ks; figure from memory, not verified this session). Hach''s own headcount is not disclosed separately.', 'USD 3.16 billion (Veralto Water Quality segment, approx.)', 3160, 'FY2024', 'segment', 'Hach is the largest business in Veralto''s Water Quality segment (which also includes Trojan Technologies, ChemTreat, OTT HydroMet, Sea-Bird, McCrometer); Hach-only revenue is not disclosed. Segment figure (~USD 3.16 bn of Veralto''s ~USD 5.23 bn FY2024 sales) is from memory of Veralto''s FY2024 10-K and could not be verified this session (search budget exhausted, fetch failures) — verify before use.', 'mixed', 'distributor', 'Hach''s own ''Hach Flow'' distributor page (nz.hach.com/flow, about five years old) lists Modotec Ltd., Akko (modotec@modotec.co.il) under Israel for Hach Flow products. No Israeli distributor was found for Hach''s core lab/water-analysis lines (DR spectrophotometers, HQ meters, 2100Q turbidimeters): searches across 43 Israeli distributor domains, Hebrew queries, hach.com''s global-distributor pages and model-number queries surfaced nothing, and Hach''s regional contact is Hach Middle East & Africa in Dubai (+971 4 303 1700). Treat the Modotec listing as stale and partial in scope, and verify.', 'low', 'Only a ~5-year-old manufacturer page for the Flow line; core lab line channel unknown.', 'company', 'verified', '+1 800-227-4224 (toll-free); +1 970-669-3050 (international line)', 'orders@hach.com; support@hach.com', 'P.O. Box 389, Loveland, CO 80539, USA (street address 5600 Lindbergh Drive, Loveland, CO per directories only)', 'https://hach.com/contact', 'HQ; fax +1 970-669-2932; export/international: export@hach.com, intl@hach.com; tech support techhelp@hach.com / support.hach.com; Middle East regional contact page https://mena.hach.com/contact');
