INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (53, 'Hanna Instruments', 'HANNA; Hanna Instruments Italia (Villafranca Padovana); edge, Checker, HALO, HI-series', 'Woonsocket, Rhode Island', 'USA', '', 'Private (family-owned — founded in Italy by Oscar and Anna Nardo; led by Martino and Pamela Nardo)', 1978, 'https://www.hannainst.com', 'Water & electrochemical analysis', 1500, 2024, 'Roughly 1,500 employees worldwide (recalled, unverified).', 'USD ~150 million (trade estimate; private)', 150, '2024 (estimate)', 'estimate', 'Hanna (Woonsocket RI / Italy) is family-owned; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'Hanna products are sold in Israel by Medent Scientific Instruments (מדנט מכשור מדעי; an extensive Hanna catalogue of pH/EC/TDS meters, electrodes and photometers on its own site), BioAnalytics (bioanalytics.co.il; Hanna pool/spa and food pH testers) and the online retailer Cannadepot (Hanna portable testers). Hanna''s own ''Find My Hanna'' page lists Israel, but the local contact was not visible in search snippets, so the official importer or exclusive distributor is not established; the companies above may be resellers of that importer.', 'medium', 'Resale verified on three Israeli sites; official importer not identified.', 'estimate', 'verified', '+1 401-765-0048', 'intsales@hannainst.com; sales@hannainst.com (US sales/technical service office, Smithfield RI)', '584 Park East Drive, Highland Industrial Park, Woonsocket, RI 02895, USA', '', 'HQ; details from Hanna general catalog v38 (copy hosted by Hanna Ecuador/Guatemala sites); US toll-free +1 800-426-6287 (270 George Washington Hwy, Smithfield RI); directories (ZoomInfo) show +1 401-765-7500 for Woonsocket');
