INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (55, 'Roche Diagnostics', 'Roche Diagnostics International Ltd; cobas; Elecsys; LightCycler; Ventana; Foundation Medicine; Accu-Chek', 'Rotkreuz (division HQ) / Basel (group HQ)', 'Switzerland', 'Roche Holding AG', 'Division of Roche Holding AG (public, SIX: ROG / RO; OTCQX: RHHBY)', 1968, 'https://diagnostics.roche.com', 'Clinical / IVD laboratory analyzers', 103600, 2024, 'Roche Group headcount (~103,600 at end-2024, Roche Annual Report 2024) — from memory, not verified this session; Diagnostics Division headcount not separately recorded. Founded: Roche 1896; diagnostics activities since 1968 (Boehringer Mannheim acquired 1998).', 'CHF 14.3 billion (Diagnostics Division, approx.)', 16731, 'FY2024', 'segment', 'Roche Diagnostics Division sales FY2024 ≈ CHF 14.3 bn (Roche Group ≈ CHF 60.5 bn). FY2025 (reported Jan 2026) was broadly similar in CHF (low-single-digit CER growth, strong-franc headwind) — exact FY2025 figure not verified this session. All figures from memory of Roche results releases; no source could be opened (search budget exhausted, fetch failures) — verify.', 'reported', 'parent_subsidiary', 'Searched ''"Roche Diagnostics" Israel distributor/נציג/יבואן'', Hebrew ''רוש דיאגנוסטיקה'', the 29 Israeli distributor domains, mr.gov.il tenders and roche.com/diagnostics.roche.com. Roche''s own diagnostics safety-officer page lists ''Roche Diagnostics Israel'' at 6 Hacharash St., Hod Hasharon, and Roche Diagnostics'' office-locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address; a Hod Hasharon job ad for a Point-of-Care Specialist selling IVD instruments and a Sheba Medical Center tender appendix listing a cobas e801 corroborate direct activity. No independent distributor for cobas/LightCycler was found; Gamidor (VENTANA tissue diagnostics) and Dyn (Diabetes Care) handle only narrow Roche Diagnostics sub-lines. Caveat: no tender award document naming the Israeli affiliate as the cobas supplier was seen.', 'high', 'Israel finding only: entity named on two official Roche pages; the direct-sales channel for cobas/LightCycler is inferred from the affiliate''s IVD sales roles and the absence of any distributor, not from an explicit statement.', 'company', 'verified', '+972 9 973 7777', '', '6 Hacharash Street, Hod Hasharon 4524079, Israel', 'https://diagnostics.roche.com/me/en/contact-forms/contact-us-support.html', 'Israel office; address/phone from a third-party directory (Roche Israel, roche.co.il), not confirmed on an official Roche page; contact_url is the Roche Diagnostics Middle East contact form; an older Accu-Chek manual lists former distributor Dyn Diagnostics, 7 Ha''Eshel St, Caesarea, +972 4 627 7090');
