INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (57, 'Siemens Healthineers – Diagnostics', 'Siemens Healthcare Diagnostics Inc. (Tarrytown, NY); formerly Bayer Diagnostics, Dade Behring, DPC; Atellica, ADVIA, Dimension, RAPIDPoint, epoc, Aptio', 'Erlangen (group HQ); Tarrytown, New York (Diagnostics segment HQ)', 'Germany', 'Siemens AG', 'Public (Xetra/FWB: SHL), majority-owned by Siemens AG (~75%); Siemens announced in Nov 2025 a plan to spin off ~30% of SHL shares to Siemens shareholders and deconsolidate Healthineers — completion status as of Oct 2026 not verified this session', 2015, 'https://www.siemens-healthineers.com', 'Clinical / IVD laboratory analyzers', 73000, 2025, 'Siemens Healthineers group headcount (~73,000 at end of FY2025, approx.; from memory of the FY2025 annual report) — Diagnostics segment headcount not separately disclosed. Founded: Siemens Healthcare GmbH established as separately managed company in 2015 (Healthineers brand 2016, IPO 2018); medical-technology roots date to 1896 (Siemens-Reiniger).', 'EUR 4.4 billion (Diagnostics segment, approx.)', 4840, 'FY2025 (Oct-2024 to Sep-2025)', 'segment', 'Diagnostics segment revenue ≈ EUR 4.4 bn in both FY2024 and FY2025 (group revenue ≈ EUR 22.4 bn FY2024, ≈ EUR 23-24 bn FY2025). From memory of Siemens Healthineers annual reports; not verified this session — verify.', 'reported', 'subsidiary', 'Siemens Healthineers sells its diagnostics in Israel through its own local organisation. The company''s Israeli site (siemens-healthineers.com/il) documents a September-2019 Atellica Solution customer event in Israel hosted by ''Mr. Haim Regev, General Manager, Siemens Healthineers Israel'' and ''Mrs. Inbal Kinamon, Head of Diagnostics, Siemens Healthineers Israel'' (seen via a search-engine extract of that page; the page itself could not be opened this session). A GlobalData note on Atellica selling prices in Israel (2022) also indicates ongoing local sales. Legal entity name, address and current management were not verified; evidence dates from 2019 but there is no indication of a change. Searches run: ''Siemens Healthineers Israel diagnostics Atellica''; contact page fetch failed.', 'medium', 'Israeli subsidiary evidenced by the company''s own Israeli web pages (via search extract, 2019); size figures from memory of annual reports, unverified this session.', 'company', 'verified', '+972 73 321 9803', 'Siemens.il@siemens.com', '14 Hamelacha Street, Park Afeq, Rosh Ha''ayin, Israel', '', 'Israel office (Siemens Healthineers entry on the Siemens ''hotline Israel'' page; email is the general Siemens Israel mailbox, undated page); global Siemens Healthineers line +49 69 797 6602 (24/7), contact.healthcare@siemens.com');
