INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (58, 'bioMérieux', 'BioFire Diagnostics; VITEK; BACT/ALERT; VIDAS; BIOFIRE FILMARRAY; SPOTFIRE; Specific Diagnostics', 'Marcy-l''Étoile (Lyon)', 'France', 'Institut Mérieux (controlling shareholder)', 'Public (Euronext Paris: BIM); majority-controlled by Institut Mérieux (Mérieux family)', 1963, 'https://www.biomerieux.com', 'Clinical / IVD laboratory analyzers', 14000, 2024, 'Approx. 14,000 employees in ~45 countries (bioMérieux 2024 reporting) — from memory, not verified this session.', 'EUR 3.98 billion (approx.)', 4378, 'FY2024', 'company', 'FY2024 sales ≈ EUR 3.98 bn (double-digit organic growth driven by BIOFIRE); FY2025 ≈ EUR 4.1-4.2 bn (approx., reported early 2026). From memory of bioMérieux results releases; not verified this session — verify.', 'reported', 'distributor', 'An extended Hebrew/English query surfaced Ilex Medical''s own catalogue page ''BIOFIRE - Ilex Medical'', which states that Ilex offers bioMérieux''s BioFire nested multiplex PCR panels (respiratory, CSF, gastro, positive blood culture, joint infection) to Israeli customers; the page is roughly 2.5 years old, so current status should be confirmed. No source names the Israeli channel for VITEK or BACT/ALERT: the 40-domain sweep, a Hebrew tender query (''מכרז VITEK 2 ביומרייה'') and an ''Israel'' query restricted to biomerieux.com returned only clinical papers, foreign contract news and unrelated pages. bioMérieux''s only Israeli entity remains Accellix (Jerusalem R&D/manufacturing, acquired 2025); upgraded from ''unclear'' to ''distributor'' on the strength of the Ilex page. Ilex Medical''s company profile (SID Israel directory) lists bioMérieux with Abbott, Hologic, Grifols, IL and Sebia among the companies it represents; not re-confirmed on biomerieux.com.', 'medium', 'Distributor''s own site confirms the BIOFIRE line; the VITEK/BACT/ALERT distributor is still unidentified and the Ilex page dates from ~2024.', 'company', 'verified', '', '', 'Shlomo Momo Ha''levi 5, Jerusalem, Israel (Accellix; third-party startup directory, unverified)', '', 'Israel office; 2 searches found no Israeli phone/email; Accellix (acquired Jan 2026, ~70 staff across San Jose CA and Jerusalem) street address only from https://slimpages.startupim.com/min_company_page/leukodx; bioMérieux Middle East hub is in Dubai; group HQ 100 Allée Louis Pasteur, 69280 Marcy-l''Étoile, France (third-party profile)');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (58, 1, 'VITEK 2 / VITEK MS PRIME', 'automated microbial ID/AST and MALDI-TOF identification');
