INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (63, 'IKA', 'IKA, IKA Works, IKA Labortechnik, Janke & Kunkel', 'Staufen im Breisgau', 'Germany', '', 'Private (family-owned)', 1910, 'https://www.ika.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 900, 2024, 'Company/exhibitor profiles: ''over 900 employees'' at 16 locations on five continents (group figure); Revelio Labs estimates ~1,060-1,120 (2025). Year approximate (recent exhibitor profile).', 'USD ~250-273 million (aggregator estimates: Prospeo 250M, ZoomInfo 272.7M); last company-stated figure >EUR 100 million (2014)', 260, 'undated aggregator estimates (c. 2024)', 'estimate', 'No current official figure; IKA stated >EUR 100M sales with ~800 staff for 2014 (Scientist Live). Current number is an aggregator estimate.', 'mixed', 'distributor', 'Medent''s own site has a dedicated ''IKA - Germany'' manufacturer page and Hebrew product categories listing IKA RCT hot-plate stirrers, vortex mixers, RC 2/RC 5 chillers and the Oven 125, and it says it imports IKA viscometers; Labotal''s overhead-stirrer page names IKA among the brands it stocks, so both are recorded as Israeli distributors. A .co.il-wide search additionally surfaced a 2012 IKA magnetic-stirrer catalogue hosted on master-cold.co.il, which is too old and indirect to record as an entity. IKA''s own dealer locator (ika.com) was not searched within the budget, so the exclusivity or split between Medent and Labotal is unknown.', 'medium', 'Two distributors established from their own sites (Medent brand page; Labotal category page); no confirmation from IKA''s side.', 'company', 'verified', '+49 7633 831-0', 'sales@ika.de', 'Janke & Kunkel-Straße 10, 79219 Staufen, Germany', '', 'HQ (IKA-Werke GmbH & Co. KG); phone/address per bionity.com listing and IKA product manual; fax +49 7633 831-98; email from IKA manual (manualslib copy)');
