INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (69, 'Andreas Hettich', 'Hettich Lab Technology, Hettich Group', 'Tuttlingen', 'Germany', 'Bregal Unternehmerkapital (investor via 2024 growth partnership; stake size not verified)', 'Private equity (Bregal Unternehmerkapital growth partnership since 2024; Hettich family remains involved)', 1904, 'https://www.hettichlab.com', 'Centrifuges', 500, 2025, 'Company website: approximately 500 employees (group head office Tuttlingen, ~18,000 m2 site). Older third-party profiles give 342 (SelectScience) and ~450 (MedicalExpo).', 'EUR ~100 million', 110, 'FY2023', 'estimate', 'Life-sciences-europe business directory lists annual sales EUR 100,000,000 (revenue date 2023-12-31) - a rounded, unaudited directory figure; Prospeo estimates only USD 25M. Treat as estimate.', 'mixed', 'distributor', 'Search ''"Hettich" centrifuge Israel distributor'' returned Eldan''s own page ''Hettich Lab Technology'' (https://eldan.biz/?p=9327, Neopharm Group) stating ''Eldan offers in Israel the whole product range by Hettich''; the page sits in Eldan''s 2016 archive (eldan.biz/2016/page/3), so the relationship is documented as of 2016 and its current status should be re-confirmed. Not cross-checked on hettichlab.com (page could not be opened). A Sigma-Aldrich Israel catalogue entry for a Hettich item also appeared but is a global catalogue listing, not distribution evidence. Hebrew search ''Hettich צנטריפוגה יבואן ישראל אלדן'' added nothing. Tooling caveat: in this session WebFetch failed with DNS errors on every host, direct HTTPS was policy-blocked by the proxy, and the shared per-turn WebSearch budget ran out before .co.il-restricted and manufacturer-site-restricted searches could run. Steps (b) manufacturer distributor page and (c) Israeli distributor site check were therefore NOT completed; only step (a) searches were done.', 'medium', 'Israeli distributor evidenced by the distributor''s own site (2016-dated, not re-confirmed by manufacturer); revenue is a directory estimate; ownership details (Bregal stake) not verified in a primary source.', 'company', 'verified', '+49 7461 705-0', 'info@hettichlab.com', 'Föhrenstraße 12, 78532 Tuttlingen, Germany', '', 'HQ; official imprint; fax +49 7461 705-1125; legal form changed Sept 2024 from GmbH & Co. KG to Andreas Hettich GmbH');
