INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (74, 'Haier Biomedical', 'Haier Biomedical; 海尔生物; Haier Biomedical UK; brands: Biobank, Smart Vaccine, DW ULT freezers', 'Qingdao, Shandong', 'China', 'Haier Group (controlling shareholder)', 'Public (SSE STAR Market: 688139); controlled by Haier Group', 2005, 'https://www.haiermedical.com', 'Lab refrigeration & cold storage', 2800, 2024, 'Headcount NOT found in snippets (2025 annual report employee section not surfaced); only an implausible aggregator range (51-100) which was ignored.', 'CNY 2.329 billion', 323.7, 'FY2025', 'company', '2025 annual report (published 30-Apr-2026): revenue RMB 2.329 billion (+1.96% YoY), net profit attributable RMB 251 million; overseas revenue a record 36% of total (Cision release; 科创板日报 via cls.cn). FY2025 H1 net profit had fallen 39%.', 'mixed', 'distributor', 'A search restricted to haiermedical.com surfaced the news item ''HB Showcases Cutting-Edge Innovations at Israel Expo'', whose snippet says Haier Biomedical''s partner Ex-Lab presented its lineup of laboratory equipment at a university expo hosted by the Weizmann Institute and the Technion, so Ex-Lab is recorded as the Israeli partner on the manufacturer''s own word. Two follow-up searches (unrestricted and .co.il-wide) could not locate Ex-Lab''s website or any Israeli page selling Haier Biomedical ULT freezers (results were Eppendorf, Nordiclab/BDL, Kalstein and household Haier retail), and the distributor-domain search returned nothing. The date of the expo is not visible in the snippet, so the partnership''s current status is unconfirmed. Haier Biomedical''s own news page names Ex-Lab (Petah Tikva) as its Israeli partner; a directory profile says EX-LAB also carries Daihan, DLab, Heal Force, Frimed and Marathon.', 'medium', 'Entity named only in a manufacturer news snippet; could not identify the company, its website or the date.', 'estimate', 'verified', '+86 532 8893 7380', '', 'Branding Building, No. 1 Haier Road, Qingdao 266101, Shandong, China (CB Insights lists No. 280 Feng Yuan Road, Qingdao)', '', 'HQ; all details from third-party aggregators with conflicting addresses; CB Insights lists +86 532 8893 1777; UK: Haier Biomedical UK Ltd, 121 Harris Way, Sunbury, +44 1932 780070; no email seen');
