INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (76, 'Verder Scientific (Retsch, Carbolite Gero, Eltra, Microtrac MRB, QATM)', 'Verder Group scientific division; brands: Retsch, Carbolite Gero, Eltra, Microtrac MRB, QATM, ERWEKA', 'Haan (North Rhine-Westphalia)', 'Germany', 'Verder International B.V. (Verder Group, Vleuten/Utrecht, Netherlands)', 'Subsidiary of Verder Group (private, family-owned)', 1959, 'https://www.verder-scientific.com', 'Elemental & materials analysis', 1300, 2025, 'Verder Scientific division page: ''more than 1,300 employees'' (another passage on the same page says ''over 1,000''); undated company-website figure. Revelio puts the wider Verder International group at ~1,491 (2025).', 'EUR 300+ million', 330, 'undated (company website, accessed 2026)', 'company', 'Division website states ''more than EUR 300 million in sales'' (undated). An older job-board profile cites ~750 employees / EUR 150 million, clearly outdated.', 'reported', 'distributor', 'General search (''Retsch'' OR ''Carbolite Gero'' OR ''Verder Scientific'' Israel distributor/נציג/יבואן) found no Israeli entity (only Verder Scientific South Africa and US pages). Domain-restricted search found multiple mrclab.com pages selling Carbolite Gero ovens/furnaces; nothing surfaced for Retsch, Eltra, Microtrac or QATM on the Israeli distributor domains. Whether MRC is the official Carbolite Gero distributor or a reseller is not stated in the snippet; Verder''s regional contact pages were not fetched.', 'medium', 'Size from the company''s own website but undated; Israeli presence verified for Carbolite Gero via MRC product pages only; Retsch (the flagship brand) remains unverified in Israel.', 'company', 'verified', '+49 2104 2333-500', 'info@verder-scientific.com', 'Retsch-Allee 1-5, 42781 Haan, Germany', 'https://www.verder-scientific.com/contact', 'HQ. Official contact page. US subsidiary Verder Scientific Inc.: 11 Penns Trail, Newtown, PA 18940, +1 866-473-8724, info-us@verder-scientific.com.');
