INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (79, 'Opentrons Labworks', 'Opentrons; products Flex, OT-2', 'Long Island City (Queens), New York', 'USA', '', 'Private (venture-backed; SoftBank-led USD 200M round in 2021 at USD 1.8bn valuation; SOSV/HAX alumnus)', 2014, 'https://opentrons.com', 'Liquid handling & lab automation', 208, 2026, 'Latka estimate (~208 in 2026, down from ~300 in 2024); other aggregators range from 100 to 501-1,000. Location sources: Prospeo says Queens, NY; a 2021 SOSV article says Brooklyn (pre-move).', 'approx. USD 45 million (2024, Latka estimate)', 45, '2024', 'estimate', 'Aggregator estimates conflict: Latka USD 45M (2024) vs Prospeo USD 12.3M. CB Insights lists a Series C-II of USD 20.1M on 5 Dec 2025; total funding estimates USD 233-271M. TrueUp shows a secondary-market valuation estimate of ~USD 0.2bn versus the 2021 USD 1.8bn headline.', 'estimate', 'distributor', 'The 40-domain sweep returned Lifegene''s own Hebrew page ''מערכות אוטומטיות לטיפול בנוזלים'' (lifegene.co.il/automated_liquid_handler), which lists both the Opentrons OT-2 and the Opentrons Flex (positioned for NGS library prep, magnetic-bead clean-up and tagmentation) and states that Opentrons solutions are available at Lifegene with full professional support - this is the distributor the user flagged as missing. No other Israeli distributor site mentioned Opentrons (the Eldan, Lumitron and Tamar hits concern Agilent, Eppendorf epMotion and Myra), and Opentrons'' own distributor page was not searched within the budget, so exclusivity is unknown. Lifegene''s own site has an Opentrons brand page.', 'medium', 'Distributor''s own product page; manufacturer confirmation not seen.', 'company', 'verified', '+1 908-869-8907', '', '45-18 Court Square West, Long Island City, NY 11101, USA', '', 'HQ. Address from Opentrons'' own product documentation. Phone from CB Insights (third party); Prospeo lists +1 347-913-5550 instead - unverified. No general email seen.');
