INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (84, 'Gilson', 'Gilson Incorporated, PIPETMAN, Gilson Medical Electronics', 'Middleton, Wisconsin', 'USA', '', 'Private', 1948, 'https://www.gilson.com', 'Liquid handling & lab automation', 800, 2024, 'Roughly 800 employees worldwide (recalled, unverified).', 'USD ~200 million (trade estimate; private)', 200, '2024 (estimate)', 'estimate', 'Gilson (Middleton WI / Villiers-le-Bel) is family-owned; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'Searched ''"Gilson" PIPETMAN Israel distributor/נציג/יבואן'', Hebrew ''גילסון פיפטות יבואן'', the 29 Israeli distributor domains and gilson.com. Gilson''s site says it sells through distribution partners in many countries via a country lookup on its ''Worldwide Distributors'' page, but no snippet names an Israeli partner, and no Israeli distributor site returned a Gilson brand page (Ornat''s pipettes category and Tamar''s ''Pipetman-compatible tips'' page appeared, neither evidencing representation). Result: no Israeli entity identified; the manufacturer''s country selector probably lists one but could not be read through search snippets. Agentek''s own vendors page (agentek.co.il/vendors) lists the brand among the manufacturers it represents in Israel (seen in a search excerpt; the manufacturer''s own distributor page was not opened). Lifegene''s own site has Gilson brand and category pages (PIPETMAN Classic/Neo, PLATEMASTER); Agentek''s vendors list also names Gilson, so there appear to be two Israeli channels.', 'medium', 'No Israeli entity found; absence of evidence only.', 'estimate', 'verified', '+1 608-836-1551', '', '3000 Parmenter Street, P.O. Box 620027, Middleton, WI 53562-0027, USA', 'https://gmlh.gilson.com/GMLHSV/services-and-support/contact.html', 'HQ (Gilson Incorporated, Global Headquarters). Toll-free +1 800-445-7661; fax +1 608-831-4451. Customer-service / tech-support emails exist on the contact page but were not visible in results.');
