INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (85, 'INTEGRA Biosciences', 'INTEGRA, VIAFLO, VOYAGER, ASSIST PLUS, VACUSAFE, MEDIACLAVE', 'Zizers', 'Switzerland', '', 'Private', 1965, 'https://www.integra-biosciences.com', 'Liquid handling & lab automation', 1000, 2024, 'INTEGRA states roughly 1,000 employees (recalled, unverified).', 'CHF ~250 million (trade estimate; private)', 290, '2024 (estimate)', 'estimate', 'INTEGRA (Zizers) is privately held; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'Searched ''"INTEGRA Biosciences" Israel distributor/נציג/יבואן'', the 29 Israeli distributor domains and integra-biosciences.com. INTEGRA''s own ''Where to buy'' country selector lists Medent - Scientific Equipment Ltd. (Beer Sheva, medent.co.il) as its distributor for Israel; an older indexed copy of the same page shows the same entry. INTEGRA has no Israeli subsidiary (its own offices are in Europe, North America and Asia-Pacific). Caveat: Medent''s own site was not checked and the listing was indexed roughly five months before today.', 'high', 'Israel finding only: named on the manufacturer''s official distributor page.', 'estimate', 'verified', '+41 81 286 95 30', '', 'Tardisstrasse 201, 7205 Zizers, Switzerland', 'https://www.integra-biosciences.com/global/en/contacts', 'HQ. Address from official contacts page; phone from BioTechniques / Datanyze listings (not visible on the official page in results). Customer-care and tech-support email links exist on the contacts page but were not shown. Second HQ in Hu