INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (86, 'BMG LABTECH', 'BMG Labtech, CLARIOstar, PHERAstar, FLUOstar Omega', 'Ortenberg', 'Germany', '', 'Private', 1989, 'https://www.bmglabtech.com', 'Microplate readers & detection', 300, 2024, 'Roughly 300 employees worldwide (recalled, unverified).', 'EUR ~70 million (trade estimate; private)', 77, '2024 (estimate)', 'estimate', 'BMG LABTECH (Ortenberg) is family-owned; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'Searched ''"BMG LABTECH" Israel distributor/נציג/יבואן'', the 29 Israeli distributor domains and bmglabtech.com. BMG LABTECH''s ''Sales & Support Offices'' page lists Zotal Ltd. (Tel Aviv) as the Israel contact, and Zotal''s own site has a BMG LABTECH brand page plus microplate-reader product pages (luminescence, fluorescence polarization, TR-FRET, AlphaScreen, LVF monochromator). BMG has no Israeli subsidiary; its own offices are in Germany, USA, UK, Australia, Japan and France. No caveats beyond BMG''s page not labelling Zotal explicitly as ''distributor'' versus office.', 'high', 'Israel finding only: confirmed on both the manufacturer''s and the distributor''s sites.', 'estimate', 'verified', '+49 781 96968-0', 'germany@bmglabtech.com', 'Allmendgrün 8, 77799 Ortenberg, Germany', 'https://bmglabtech.com/de/kontakt', 'HQ. Official contact page shows address + phone, no email (contact form). Email germany@bmglabtech.com and fax +49 781 96968-67 come from a 2018 BMG contact-addresses PDF (med-fom-avgaylab.sites.olt.ubc.ca) - verify. US office: usa@bmglabtech.com (Cary, NC).');
