INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (87, 'Repligen', 'TangenX, Spectrum Labs (KrosFlo), CTech / C Technologies, ARTeSYN, Avitide, Metenova, Tantti, OPUS', 'Waltham, Massachusetts', 'USA', '', 'Public (NASDAQ: RGEN)', 1981, 'https://www.repligen.com', 'Bioprocess & filtration', 1900, 2024, 'Approx. 1,900 employees as recalled from Repligen''s FY2024 Form 10-K; could not be re-verified this run (WebFetch/proxy unavailable), so treat as approximate.', 'USD 634.5 million (recalled, unverified this run)', 634.5, 'FY2024', 'company', 'FY2024 10-K figure (recalled; FY2025 revenue was guided at roughly USD 700M). Figures recalled from company statements / filings and not re-verified online in this session.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Round 3 ran the brand restricted to the 40 Israeli distributor domains (only SEC filings surfaced; no Israeli site mentions Repligen, XCell ATF, OPUS, TangenX, KrosFlo or SoloVPE), a Hebrew-only query (''Repligen יבואן נציגות בישראל ביופרוסס'') and an ''Israel distributor'' query restricted to repligen.com; none named an Israeli distributor or office. Repligen''s distributors page repeats that products are marketed through a direct commercial organisation in the US, Europe and Asia plus strategic partners and distributors in select markets, and its locations page lists only US sites and Bengaluru. Result unchanged from round 2: no Israeli entity identified; Israel is most likely served directly from Repligen Europe or by an unnamed partner.', 'low', 'Absence of evidence only.', 'company', 'partial', '+1 781-250-0111', '', '41 Seyon Street, Building 1, Suite 100, Waltham, MA 02453, USA', '', 'HQ. From official investor site; toll-free +1 800-622-2259, fax +1 781-250-0115. Only role email seen is investor relations investors@repligen.com (no general/sales email).');
