INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (88, 'ZwickRoell', 'Zwick, Roell, Zwick Roell, Indentec, ZwickRoell Group', 'Ulm', 'Germany', '', 'Private (family-owned)', 1854, 'https://www.zwickroell.com', 'Thermal analysis & materials testing', 1800, 2025, 'ZwickRoell Ausbildungsbroschüre 2025 (company PDF): ''more than 1,800 employees worldwide, more than 1,200 at the Ulm-Einsingen headquarters''.', 'EUR 304 million', 334.4, 'FY2023', 'company', 'Same company brochure gives revenue of EUR 304 million for 2023; the figure is split across a line break in the PDF text (''30 / 4''), so the exact reading carries some uncertainty. No 2024/2025 figure found. IHK Ulm (2026) reports a EUR 11.2 million training-centre investment at the HQ.', 'reported', 'distributor', 'Searched the brand generically (English/Hebrew), across 27 Israeli lab-distributor domains, on zwickroell.com and for the partner''s own name. ZwickRoell''s own ''Locations around the world'' page names GLOBUS Technical Equipment Ltd. in the Kadima Industrial Zone as its Israeli partner (phone number and contact form). No website for Globus was found and it does not appear on any of the usual Israeli lab-distributor sites, so it is an industrial/technical-equipment agent rather than a lab-supply house.', 'high', 'Israeli partner named on the manufacturer''s official locations page; only the partner''s website could not be located.', 'company', 'verified', '+49 7305 10-0', 'info@zwickroell.com', 'August-Nagel-Str. 11, 89079 Ulm, Germany', '', 'HQ. From official imprint; fax +49 7305 10-11200; service hotline +49 7305 10-11225.');
