INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (89, 'Kewaunee Scientific', 'Kewaunee, Nu Aire / NuAire (subsidiary since Nov 2024), Kewaunee Labway India', 'Statesville, North Carolina', 'USA', '', 'Public (NASDAQ: KEQU)', 1906, 'https://www.kewaunee.com', 'Lab furniture & fume hoods', 2800, 2025, 'Headcount NOT found in snippets: FY2026 10-K (filed mid-2026) surfaced but its Human Capital section was not shown; Motley Fool''s 1,231 is AI-generated and pre-dates the filing, so ignored.', 'USD 282.0 million', 282, 'FY2026 (ended 30-Apr-2026)', 'company', '8-K / earnings release 23-Jun-2026: FY2026 sales USD 281,999,000, +17.3% vs USD 240,472,000 in FY2025; Lab Products Group (ex-Domestic) USD 214.9 million (+19.8%); net earnings USD 9.6 million (USD 3.22 diluted EPS); backlog USD 165.9 million at 30-Apr-2026; Nu Aire seller notes repaid.', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''Kewaunee'' laboratory furniture Israel distributor/נציג/יבואן; Hebrew query ריהוט מעבדה / מנדפים with ''Kewaunee'' (extended); and ''Kewaunee'' restricted to 18 Israeli distributor domains (no hits). Kewaunee''s own site lists sales offices/subsidiaries in the US, India, Saudi Arabia and Singapore, with Middle East sales handled via its Singapore/India subsidiaries and regional dealers (a 2010 shareholder letter mentions Middle East dealer representation). Its ''Find a Kewaunee Dealer'' page snippet (US dealers plus a Hong Kong dealer) was truncated, so an Israeli dealer listing cannot be ruled out; the page could not be fetched. No Israeli entity found.', 'medium', 'Revenue official (SEC filing); headcount not captured. Israel: nothing found after three searches, but the manufacturer''s dealer map was not fully readable - treat none_found as provisional.', 'estimate', 'partial', '+1 704-873-7202', '', '2700 West Front Street, Statesville, NC 28677, USA', '', 'HQ. Third-party directory listings (Tradeline, Plunkett Research); fax +1 704-873-1275. An older exhibitor listing gives PO Box 1842, Statesville NC 28687 and +1 704-871-3212. No email seen.');
