INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (90, 'WALDNER Laboreinrichtungen', 'WALDNER, Waldner Group (Hermann WALDNER GmbH & Co. KG, WALDNER Dosomat, Hohenloher Spezialmöbelwerk)', 'Wangen im Allgäu', 'Germany', 'WALDNER Group (Hermann WALDNER GmbH & Co. KG)', 'Private (family-owned)', 1908, 'https://www.waldner.de', 'Lab furniture & fume hoods', 1600, 2025, 'WALDNER''s own job listing: over 1,600 employees group-wide, over 1,000 of them at the Wangen im Allgäu production site; Schwäbische Zeitung reports 114 apprentices at the HQ (~10% of staff there), consistent with that. Undated job-ad figure.', 'EUR ~200 million (group, trade estimate; private)', 220, '2024 (estimate)', 'estimate', 'No usable 2024/2025 revenue figure: Indeed gives only a range (EUR 85-425 million), an Implisense entry says 2023 revenue increased without a number; chemie.de (Jun-2024) reports > EUR 11 million investment in new production machinery at Wangen.', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''Waldner'' laboratory furniture fume hoods Israel distributor/נציג/יבואן; Hebrew query ריהוט מעבדה / מנדפים with ''Waldner'' (extended); and ''Waldner'' restricted to 18 Israeli distributor domains (no hits - only unrelated MRC pages). Results named partners elsewhere only (Labokraft, exclusive Hungarian distributor since 2006; Analysis doo, Balkans; GD Waldner / Waldner Inc. for India / North America). The only Israeli fume-hood company surfaced was Mintz Lab Systems (Ness Ziona), a local manufacturer not described as a Waldner partner. Waldner''s distributor/contact page was not fetched.', 'medium', 'Headcount from a company job advertisement (undated), no revenue; no Israeli representation found after three searches, manufacturer''s partner list unchecked.', 'company', 'partial', '+49 7522 9860', '', 'Haidösch 1, 88239 Wangen im Allgäu, Germany', '', 'HQ (WALDNER Laboreinrichtungen SE & Co. KG). Address from official site; phone from Spectaris / SelectScience listings. No email - official site routes enquiries through a contact form. Parent WALDNER Holding: Anton-Waldner-Straße 10-16, 88239 Wangen im Allgäu.');
