INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (94, 'BRAND (incl. VACUUBRAND)', 'BRAND Group; BRANDTECH Scientific (USA/Canada); VACUUBRAND; VITLAB; Transferpette, Dispensette, BLAUBRAND', 'Wertheim', 'Germany', '', 'Private (family-owned)', 1949, 'https://www.brand.de', 'Liquid handling & lab automation', 500, 2025, 'Company recruitment text (Stepstone, BRAND GMBH + CO KG): about 500 people develop and manufacture at the Wertheim site; BRAND, VACUUBRAND and VITLAB together form a group of about 1,000 employees worldwide. Undated job-ad figures.', 'EUR ~150 million (group, trade estimate; private)', 165, '2024 (estimate)', 'estimate', 'No revenue figure found (GmbH & Co KG; Bundesanzeiger not surfaced).', 'mixed', 'distributor', 'The 40-domain sweep returned Labotal''s own product and news pages: a ''Brand Pipettors, New Series: Transferpette α'' page, single-channel pipettor category pages, VACUUBRAND ME 2 NT, ME 4 NT and MV-10C-EX pump pages, and a company-news page stating that Labotal is an authorised VACUUBRAND distributor for the laboratory segment and began carrying BRAND liquid-handling products in 2018. No other Israeli distributor site mentioned BRAND or VACUUBRAND. The manufacturers'' own distributor pages (brand.de, vacuubrand.com) were not searched within the budget, so exclusivity and other channels (e.g. BRAND consumables via general lab-supply houses) are unknown.', 'medium', 'Distributor''s own site is explicit about both brands; manufacturer confirmation not seen.', 'company', 'verified', '+49 9342 808-0', 'info@brand.de', 'Otto-Schott-Str. 25, 97877 Wertheim, Germany', 'https://brand.de/en/contact/how-to-find-us', 'HQ (BRAND GMBH + CO KG). Fax +49 9342 808-236. VACUUBRAND GMBH + CO KG is a separate company at Alfred-Zippe-Straße 4, 97877 Wertheim, email info@vacuubrand.com.');
