INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (97, 'Nabertherm', 'Nabertherm GmbH; Nabertherm Inc. (USA)', 'Lilienthal (near Bremen)', 'Germany', '', 'Private', 1947, 'https://nabertherm.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 600, 2026, '''About 600 employees worldwide'' per a 2026 Nabertherm product brochure; 2022 anniversary releases said c. 500 (English) / c. 550 in Lilienthal (German). Own subsidiaries in UK, Spain, France, Netherlands, Switzerland, Italy, China, USA.', 'EUR 65 million', 72, 'FY2021', 'company', 'Company''s 75th-anniversary press release (Sept 2022) gives c. EUR 65M revenue for 2021; Craft.co lists EUR 77.6M for FY2022 (unsourced). No 2024/2025 figure found.', 'reported', 'distributor', 'A search restricted to nabertherm.com returned the official World-Wide Sales page whose snippet names Electrotherm Marketing 1978 Ltd, Migdal Haemek (sales@electrotherm.co.il), as the agent for Israel. A follow-up search restricted to electrotherm.co.il confirmed the distributor''s own Hebrew site (אלקטרוטרם) with Nabertherm product pages for melting furnaces (K 180/12), high-temperature furnaces, chamber/drying ovens (NA 1000/45 LS, 4500 WK), ceramic kilns, tube furnaces and the B400/C440/P470 controller documentation. Both the manufacturer''s locator and the distributor''s site therefore agree; the earlier round-1 locator snippet simply had not shown the Israel entry.', 'high', 'Named on Nabertherm''s official sales locator and confirmed by the distributor''s own Nabertherm product pages.', 'company', 'verified', '+49 4298 922-0', 'contact@nabertherm.de', 'Bahnhofstraße 20, 28865 Lilienthal, Germany', '', 'HQ. From official site footer/downloads pages; fax +49 4298 922-129; warehouse delivery address Dr.-Sasse-Straße 31, 28865 Lilienthal.');
